                let key = counter.to_ascii_lowercase();
                let current = player_state.counters.get(&key).copied().unwrap_or(0);
                player_state.counters.insert(
                    key.clone(),
                    current
                        .checked_add(amount)
                        .ok_or(ExecutionError::ArithmeticOverflow)?,
                );
                state
                    .put_player(player_state)
